import copy
def rename_receiver(config,old,new):
    result=copy.deepcopy(config)
    if not isinstance(old,str) or not old or not isinstance(new,str) or not new or old==new:raise ValueError("distinct receiver names required")
    found=[r for r in result["receivers"] if r["name"]==old]
    if len(found)!=1 or any(r["name"]==new for r in result["receivers"]):raise ValueError("one old receiver and unused new name required")
    found[0]["name"]=new
    def walk(route):
        if route.get("receiver")==old:route["receiver"]=new
        for child in route.get("routes",[]):walk(child)
    walk(result["route"])
    return result
```

